package org.telegram.messenger.tetogram;
import org.junit.Test;
import static org.junit.Assert.*;
public class AppearanceContrastTest {
 private int nativeColor(String name){return name.equals("chat_wallpaper")||name.contains("Background")||name.equals("chat_inBubble")||name.equals("chat_outBubble")?0xffffffff:0xff000000;}
 @Test public void untouchedExternalThemeIsNotRewritten(){AppearanceConfig c=new AppearanceConfig();assertTrue(AppearanceContrast.issues(new AppearanceConfig.Style(),c.resolve(AppearanceConfig.Context.direct(0,0)),false,k->0xffffffff).isEmpty());}
 @Test public void transparentTextIsRejectedAndRepairIsUndoableByCopy(){AppearanceConfig c=new AppearanceConfig();AppearanceConfig.Style draft=c.edit("global");draft.color(false,"chat_inBubble",0xffffffff);draft.color(false,"chat_messageTextIn",0x00ffffff);AppearanceConfig.Style before=draft.copy();AppearanceConfig.Resolved r=c.resolve(AppearanceConfig.Context.direct(0,0));assertTrue(AppearanceContrast.issues(draft,r,false,this::nativeColor).contains("chat_messageTextIn"));AppearanceContrast.repair(draft,r,false,this::nativeColor);assertTrue(AppearanceContrast.issues(draft,c.resolve(AppearanceConfig.Context.direct(0,0)),false,this::nativeColor).isEmpty());assertEquals(Integer.toString(0x00ffffff),before.values.get("light.chat_messageTextIn"));}
 @Test public void lightRepairDoesNotChangeDarkPalette(){AppearanceConfig c=new AppearanceConfig();AppearanceConfig.Style s=c.edit("global");s.color(false,"actionBarDefault",0xffffffff);s.color(false,"actionBarDefaultIcon",0xffffffff);s.color(true,"actionBarDefaultIcon",0xffabcdef);AppearanceContrast.repair(s,c.resolve(AppearanceConfig.Context.direct(0,0)),false,this::nativeColor);assertEquals(Integer.toString(0xffabcdef),s.values.get("dark.actionBarDefaultIcon"));assertEquals(Integer.toString(0xff000000),s.values.get("light.actionBarDefaultIcon"));}
 @Test public void activeAndInactiveSectionIconsCanHaveIndependentContrast(){AppearanceConfig c=new AppearanceConfig();AppearanceConfig.Style s=c.edit("global");s.color(false,"section.background",0xff000000);s.color(false,"section.activeBackground",0xffffffff);s.color(false,"section.text",0xff000000);s.color(false,"section.activeText",0xffffffff);AppearanceContrast.repair(s,c.resolve(AppearanceConfig.Context.direct(0,0)),false,this::nativeColor);assertEquals(Integer.toString(0xffffffff),s.values.get("light.section.text"));assertEquals(Integer.toString(0xff000000),s.values.get("light.section.activeText"));}
}
